  const pmiDirection = !pmi ? null : pmi.previous === null ? null : pmi.actual > pmi.previous ? "improving" : pmi.actual < pmi.previous ? "deteriorating" : "stable";

  return {
    boe_bias: boeBias,
    boe_bias_score: events.length ? score : null,
    boe_bias_reasons: reasons.slice(0, 5),
    latest_uk_event: completed[0] || null,
    upcoming_uk_events: upcoming,
    uk_composite_pmi: pmi ? pmi.actual : null,
    uk_composite_pmi_direction: pmiDirection,
    uk_events_found: events.length
  };
}

const gbpusdPayload = node(NODES.gbpusd);
const gbpusdPrice = num(gbpusdPayload && gbpusdPayload.data && gbpusdPayload.data.amount);
const us2y = series(node(NODES.us2y), false);
const us10y = series(node(NODES.us10y), false);
const uk5y = boeSeries(node(NODES.uk5y));
const uk10y = boeSeries(node(NODES.uk10y));
const bankRate = boeSeries(node(NODES.bankRate));
const uk3m = series(node(NODES.uk3m), false);
const vix = series(node(NODES.vix), false);
const dxy = series(node(NODES.dxy), true);
const uk = ukCalendar(node(NODES.ukCalendar));

// US-UK 10Y spread impulse: maturity-matched, both legs daily and authoritative.
const usUk10ySpreadD5Bps =
  us10y.latest !== null && uk10y.latest !== null && us10y.d5 !== null && uk10y.d5 !== null
    ? ((us10y.latest - uk10y.latest) - ((us10y.latest - us10y.d5) - (uk10y.latest - uk10y.d5))) * 100
    : null;

// Core missing input (GBP/USD spot) means no usable pack, so the agent can never
// produce a falsely usable call.
if (gbpusdPrice === null) {
  return [];
}

const missing = [];
if (us2y.d5 === null) missing.push("us_2y_d5_bps");
if (uk5y.d5 === null) missing.push("uk_5y_d5_bps");
if (usUk10ySpreadD5Bps === null) missing.push("us_uk_10y_spread_d5_bps");
if (vix.latest === null) missing.push("vix_level");
if (dxy.latest === null) missing.push("dxy_level");
if (bankRate.latest === null) missing.push("uk_bank_rate");
if (uk.boe_bias === null) missing.push("boe_bias");
if (uk.latest_uk_event === null) missing.push("latest_uk_event");
if (uk.uk_composite_pmi === null) missing.push("uk_composite_pmi");
// No authoritative UK stress proxy exists in this platform.
missing.push("uk_stress_flag", "global_growth_regime");

const availableInputs = {
  gbpusd_price: gbpusdPrice,
  gbpusd_price_date: new Date().toISOString().slice(0, 10),

  vix_level: vix.latest,

  dxy_level: dxy.latest,
  dxy_d1_pct: dxy.d1,

  us_2y_yield: us2y.latest,
  us_2y_d5_bps: us2y.d5 === null ? null : us2y.d5 * 100,
  us_10y_yield: us10y.latest,
  us_10y_d5_bps: us10y.d5 === null ? null : us10y.d5 * 100,

  // UK rate data. FRED has no UK 2Y series, so the front-end and relative-rate
  // factors use the Bank of England IADB daily gilt yields (IUDSNPY / IUDMNPY) and
  // the Official Bank Rate (IUDBEDR) - the same national-central-bank REST pattern
  // already used live for Germany 2Y via the Bundesbank.
  uk_2y_yield: null,
  uk_2y_d5_bps: null,
  us_uk_2y_spread_d5_bps: null,
  uk_5y_yield: uk5y.latest,
  uk_5y_d5_bps: uk5y.d5 === null ? null : uk5y.d5 * 100,
  uk_10y_yield: uk10y.latest,
  uk_10y_d5_bps: uk10y.d5 === null ? null : uk10y.d5 * 100,
  uk_bank_rate: bankRate.latest,
  uk_bank_rate_d5_bps: bankRate.d5 === null ? null : bankRate.d5 * 100,
  uk_3m_interbank: uk3m.latest,
  us_uk_10y_spread_d5_bps: usUk10ySpreadD5Bps,

  boe_bias: uk.boe_bias,
  boe_bias_score: uk.boe_bias_score,
  boe_bias_reasons: uk.boe_bias_reasons,
  latest_uk_event: uk.latest_uk_event,
  upcoming_uk_events: uk.upcoming_uk_events,
  uk_composite_pmi: uk.uk_composite_pmi,
  uk_composite_pmi_direction: uk.uk_composite_pmi_direction,
  uk_events_found: uk.uk_events_found,

  uk_stress_flag: null,
  global_growth_regime: null
};

return [
  {
    json: {
      asset: "GBP",
      snapshot_id: null,
      snapshot_date: new Date().toISOString().slice(0, 10),
      run_time_et: new Date().toISOString(),
      provider_status: "READ_AT_AGENT_RUNTIME",
      session_status: "WEEKDAY_ACTIVE_TIME_V1",
      isolation_rule: "This Layer 1 agent may only use the GBP input pack above and the GBP logic document. It must not read other agent outputs.",
      execution_question: "Based on confirmed value-driving factors available at execution time, what is the likely 24H direction of GBP?",
      available_inputs: availableInputs,
      missing_inputs: missing,
      missing_rule: "Unavailable inputs are scored NEUTRAL and never inferred."
    }
  }
];

// GBP Layer 1 deterministic 24H verdict gate (draft v0.2).
// Mirrors the shared Layer 1 deterministic conviction contract used by the other
// live asset agents field-for-field, so the Layer 2 trade selection agent and the
// Dashboard Writer consume GBP rows with no new field handling. The model's own
// conviction is ignored; this node is the only conviction source. Weights remain
// provisional hypotheses pending historical replay.
const item = $input.first().json;

const WEIGHTS = { F1: 20, F2: 16, F3: 20, F4: 12, F5: 8, F6: 10, F7: 6, F8: 4, F9: 2, F10: 2 };
const LOGIC_DOCUMENT = "agent_gbp_direction.md";
const LOGIC_DOCUMENT_VERSION = "0.1_research_baseline";

const supplied = item.factor_breakdown && typeof item.factor_breakdown === "object" ? item.factor_breakdown : {};
const missingInputs = Array.isArray(item.missing_inputs) ? item.missing_inputs.slice() : [];

let bullish = 0;
let bearish = 0;
let neutral = 0;
let bullishCount = 0;
let bearishCount = 0;
let neutralCount = 0;

const factorBreakdown = {};
for (const [id, weight] of Object.entries(WEIGHTS)) {
  const entry = supplied[id] && typeof supplied[id] === "object" ? supplied[id] : {};
  const raw = typeof supplied[id] === "string" ? supplied[id] : entry.signal;
  const signal = raw === "BULLISH" || raw === "BEARISH" ? raw : "NEUTRAL";
  // Unknown or unavailable signals are scored neutral; they are never inferred.
  factorBreakdown[id] = { ...entry, signal, weight };
  if (signal === "BULLISH") {
    bullish += weight;
    bullishCount++;
  } else if (signal === "BEARISH") {
    bearish += weight;
    bearishCount++;
  } else {
    neutral += weight;
    neutralCount++;
  }
}

const active = bullish + bearish;
const participation = active;
const bullishArgument = active > 0 ? Math.round((bullish / active) * 100) : 0;
const bearishArgument = active > 0 ? Math.round((bearish / active) * 100) : 0;
const neutralPct = Math.round(neutral);
const netEdge = bullishArgument - bearishArgument;
const absEdge = Math.abs(netEdge);
const weightMargin = Math.abs(bullish - bearish);

const baseDirection = bullish > bearish ? "BULLISH" : bearish > bullish ? "BEARISH" : "NO_CLEAR_BIAS";
const direction =
  baseDirection === "NO_CLEAR_BIAS"
    ? "NO_CLEAR_BIAS"
    : active < 50 || weightMargin < 15 || absEdge < 20
      ? `${baseDirection}_LEAN`
      : baseDirection;

const winningArgument =
  baseDirection === "BULLISH" ? bullishArgument : baseDirection === "BEARISH" ? bearishArgument : 0;
const participationCap = Math.min(participation, 80);
const conviction =
  baseDirection === "NO_CLEAR_BIAS" ? 0 : Math.round(winningArgument * (participationCap / 100));

const verdictStrength =
  absEdge >= 40 && participation >= 70
    ? "VERY_STRONG"
    : absEdge >= 25 && participation >= 50
      ? "STRONG"
      : absEdge >= 15
        ? "MODERATE"
        : "WEAK";

const reason =
  `24H deterministic GBP score: bull case ${bullishArgument}%, bear case ${bearishArgument}%, ` +
  `directional participation ${participation}%, neutral/unavailable ${neutralPct}%, ` +
  `net edge ${netEdge > 0 ? "+" : ""}${netEdge}. Missing inputs ` +
  `(${missingInputs.length ? missingInputs.join(", ") : "none"}) are scored neutral and never inferred.`;

const weightedScore = {
  bullish_weight: bullish,
  bearish_weight: bearish,
  neutral_weight: neutral,
  active_weight: active,
  weight_margin: weightMargin
};

const convictionModel = {
  bull_case: bullishArgument,
  bear_case: bearishArgument,
  winning_side: baseDirection,
  directional_participation: participation,
  net_edge: netEdge,
  final_conviction: conviction,
  verdict_strength: verdictStrength,
  final_conviction_logic: reason,

  bullish_argument_pct: bullishArgument,
  bearish_argument_pct: bearishArgument,
  neutral_pct: neutralPct,
  neutral_evidence_pct: neutralPct,
  active_participation_pct: participation,
  directional_participation_pct: participation,
  net_edge_pct: netEdge,

  weighted_edge: Math.abs(netEdge) / 100,
  raw_conviction: conviction,
  base_conviction: conviction,
  participation,
  participation_cap: participationCap,
  conflict_penalty: 0,
  missing_input_penalty: 0,
  agreement_boost: 0,
  bull_case_weight: bullish,
  bear_case_weight: bearish,
  neutral_weight: neutral
};

const timeframeModels = {
  "24h": {
    direction,
    conviction,
    reason,
    factor_breakdown: factorBreakdown,
    weighted_score: weightedScore,
    conviction_model: convictionModel
  }
};

const riskFlags = [
  "PROVISIONAL_WEIGHTS",
  "GBP_24H_ONLY",
  ...(Array.isArray(item.risk_flags) ? item.risk_flags : []),
  ...missingInputs
];

const fullOutput = {
  asset: "GBP",
  layer: "layer_1_raw",
  logic_document: LOGIC_DOCUMENT,
  logic_document_version: LOGIC_DOCUMENT_VERSION,

  direction_24h: direction,
  conviction_24h: conviction,
  reason_24h: reason,

  factor_breakdown: factorBreakdown,
  weighted_score: weightedScore,
  conviction_model: convictionModel,
  timeframe_models: timeframeModels,

  score_bullish: bullishCount,
  score_bearish: bearishCount,
  score_neutral: neutralCount,
  non_neutral_count: bullishCount + bearishCount,

  market_inputs: item.market_inputs || {},
  missing_inputs: missingInputs,
  reasoning_summary: reason,
  risk_flags: riskFlags
};

// The live agent_outputs table has no asset / market_inputs / missing_inputs /
// timeframe_models / non_neutral_count / risk_flags columns, so those documented
// fields live inside full_output and the run is not failed by an unknown column.
// warnings is a real column and carries the risk flags.
const {
  asset: _asset,
  market_inputs: _marketInputs,
  missing_inputs: _missingInputs,
  timeframe_models: _timeframeModels,
  non_neutral_count: _nonNeutralCount,
  risk_flags: _riskFlags,
  ...rowSafe
} = item;

return [
  {
    json: {
      ...rowSafe,

      agent_name: "GBP",
      layer: 1,
      logic_document: LOGIC_DOCUMENT,
      logic_document_version: LOGIC_DOCUMENT_VERSION,

      call_24h_direction: direction,
      call_24h_conviction: conviction,
      call_24h_reason: reason,
      direction_24h: direction,
      conviction_24h: conviction,

      factor_breakdown: factorBreakdown,
      weighted_score: weightedScore,
      conviction_model: convictionModel,

      score_bullish: bullishCount,
      score_bearish: bearishCount,
      score_neutral: neutralCount,

      warnings: riskFlags,
      reasoning_summary: reason,

      full_output: fullOutput,
      raw_agent_output: fullOutput
    }
  }
];
